import themepack
theme = (value + '|').split('|')[0]
if not theme:
	return []
try:
	rows = themepack.list_files(theme)
except Exception:
	return []
out = []
for r in rows:
	if not r['editable']:
		continue
	mark = ''
	try:
		if themepack.read_file(theme, r['name'])['modified']:
			mark = u'  \u25cf'
	except Exception:
		pass
	# The marker rides on the NAME. A column of its own needs a header,
	# and an empty header title falls back to the field name -- which is
	# how a 26px column came to be labelled 'sta'.
	out.append({'name': r['name'] + mark})
return out

